if(strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'))==='GET')$reply(200,['configured'=>nbc_gemini_api_key()!=='']);
if(strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'))!=='POST')$reply(405,['message'=>'طريقة الطلب غير مدعومة.']);
if(nbc_gemini_api_key()==='')$reply(503,['message'=>'مساعد الذكاء الاصطناعي غير مهيأ بعد. أضف مفتاح Gemini على الخادم.']);
