$source=trim((string)($input['source_text']??''));$fileContent=null;$filename='';
if(!empty($input['source_path'])){$relative=(string)$input['source_path'];$id=(int)$currentInstructor['id'];if(!preg_match('/^uploads\/assessment-sources\/q_'.$id.'_([a-f0-9]{32})\.(pdf|docx|txt)$/',$relative,$match))$reply(403,['message'=>'الملف لا ينتمي إلى حسابك أو مساره غير صالح.']);$filename=basename($relative);$path=__DIR__.'/../../'.$relative;if(!is_file($path)||filesize($path)>12*1024*1024)$reply(404,['message'=>'الملف غير موجود أو يتجاوز حد المعالجة.']);$ext=strtolower(pathinfo($filename,PATHINFO_EXTENSION));
  if($ext==='txt'){$source=trim((string)file_get_contents($path));}
