$courseId=(int)($input['course_id']??0);if($courseId){$check=$pdo->prepare('SELECT 1 FROM courses c WHERE c.id=? AND (c.instructor_id=? OR EXISTS(SELECT 1 FROM course_instructors ci WHERE ci.course_id=c.id AND ci.instructor_id=?))');try{$check->execute([$courseId,(int)$currentInstructor['id'],(int)$currentInstructor['id']]);}catch(Throwable $e){$check=$pdo->prepare('SELECT 1 FROM courses WHERE id=? AND instructor_id=?');$check->execute([$courseId,(int)$currentInstructor['id']]);}if(!$check->fetchColumn())$reply(403,['message'=>'لا تملك صلاحية هذا الكورس.']);}
